import { spawn } from 'child_process'
import { Shescape } from 'shescape'

export interface CommandOutput {
  /**
   * Any stdout generated by the command
   */
  stdout: string
  /**
   * Any stderr generated by the command
   */
  stderr: string
  /**
   * The command's exit code
   */
  code: number
}

/**
 * Runs an arbitrary command in the shell, passing any arguments and a working
 * directory. The shell arguments will be sanitized before passing them to the
 * command.
 *
 * NOTE for the future: As of now, the function will simply sanitize everything.
 * If we do end up having to call this with actual arguments at some point,
 * devise a better mechanism then. For now, we're playing it safe.
 *
 * @param   {string}                    command  The command to run.
 * @param   {string[]}                  argv     Any arguments to pass to the command.
 * @param   {string}                    cwd      The working directory for the command.
 * @param   {boolean|string|undefined}  shell    Whether to use a shell for running the command.
 *
 * @return  {CommandOutput}                      Returns an object with keys stdout, stderr, and code.
 */
export async function runShellCommand (command: string, argv: string[], cwd: string, shell?: boolean|string|undefined): Promise<CommandOutput> {
  const stdout: string[] = []
  const stderr: string[] = []
  let finalCode = 0

  await new Promise<void>((resolve, reject) => {
    const shescape = new Shescape({ shell })
    // Taken from the shescape documentation: https://github.com/ericcornelissen/shescape/blob/HEAD/docs/recipes.md#spawncommand-args-options
    const treatedArgv = shell !== undefined && shell !== false
      ? // When the `shell` option is configured, arguments should be quoted
      shescape.quoteAll(argv)
      : // When the `shell` option is NOT configured, arguments should NOT be quoted
      shescape.escapeAll(argv)

    const proc = spawn(command, treatedArgv, { shell, cwd })

    proc.stdout.on('data', (data) => {
      stdout.push(String(data))
    })

    proc.stderr.on('data', (data) => {
      stderr.push(String(data))
    })

    proc.on('close', (code: number, _signal) => {
      finalCode = code
      resolve()
    })

    proc.on('error', (err) => {
      reject(err)
    })
  })

  return {
    stdout: stdout.join(''),
    stderr: stderr.join(''),
    code: finalCode
  }
}
